function validate([nums]) {
  if (!Array.isArray(nums)) return 'nums must be a list of numbers.';
  const n = nums.length;
  if (n < 1 || n > 1000) return 'nums needs 1 to 1000 values.';
  const seen = new Array(n + 1).fill(false);
  for (const value of nums) {
    if (!Number.isInteger(value) || value < 1 || value > n) return 'Each value is between 1 and nums.length.';
    if (seen[value]) return 'The values of nums must be distinct.';
    seen[value] = true;
  }
  return null;
}

