function numOfWays(nums) {
  const MOD = 1000000007;
  const n = nums.length;
  const choose = [];
  for (let total = 0; total <= n; total++) {
    choose.push(new Array(total + 1).fill(1));
    for (let k = 1; k < total; k++) {
      choose[total][k] = (choose[total - 1][k - 1] + choose[total - 1][k]) % MOD;
    }
  }

  function multiply(a, b) {
    return Number((BigInt(a) * BigInt(b)) % BigInt(MOD));
  }

  function ways(order) {
    if (order.length <= 2) {
      return 1;
    }
    const root = order[0];
    const smaller = order.filter((value) => value < root);
    const larger = order.filter((value) => value > root);
    const interleavings = choose[order.length - 1][smaller.length];
    return multiply(multiply(interleavings, ways(smaller)), ways(larger));
  }

  return (ways(nums) - 1 + MOD) % MOD;
}

