function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 7);
  const nums = Array.from({ length: n }, (_, i) => i + 1);
  const style = rand();
  if (style < 0.1) return [nums];
  if (style < 0.15) return [nums.reverse()];
  if (style < 0.3) {
    // Insert in breadth-first order of a balanced tree, giving a bushy shape.
    const order = [];
    const queue = [[1, n]];
    for (let i = 0; i < queue.length; i++) {
      const [low, high] = queue[i];
      if (low > high) continue;
      const middle = low + Math.floor(rand() * (high - low + 1));
      order.push(middle);
      queue.push([low, middle - 1], [middle + 1, high]);
    }
    return [order];
  }
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
